def build_agent(sandbox):
    # Create the anchored base at x=-2.0, y=0.0
    base = sandbox.add_anchored_base(x=-2.0, y=0.0, width=0.1, height=0.1, density=400.0)

    # First arm segment (longer to reach pit)
    arm1 = sandbox.add_beam(x=-2.0, y=0.0, width=0.2, height=0.1, angle=0, density=300.0)
    joint1 = sandbox.add_revolute_joint(base, arm1, anchor_point=(-2.0, 0.0), enable_motor=True, motor_speed=0.0, max_motor_torque=100.0)

    # Add scoop at the end of the first arm
    scoop = sandbox.add_scoop(x=-2.0, y=0.0, width=0.1, height=0.1, density=280.0)
    joint2 = sandbox.add_revolute_joint(arm1, scoop, anchor_point=(-2.0, 0.0), enable_motor=True, motor_speed=0.0, max_motor_torque=100.0)

    return (base, joint1, joint2)

def agent_action(sandbox, agent_body, step_count):
    # Access joints from build_agent
    # Assuming joint1 and joint2 are available in the scope
    if sandbox.has_central_wall():
        if step_count < 10:
            # Rotate first arm to reach pit
            joint1.motorSpeed = 0.5
        elif 10 <= step_count < 20:
            # Scoop sand
            joint1.motorSpeed = 0.0
            joint2.motorSpeed = 0.0
        elif 20 <= step_count < 30:
            # Lift scoop over wall
            joint2.motorSpeed = 1.0
        elif 30 <= step_count < 40:
            # Move to hopper and deposit
            joint1.motorSpeed = -0.5
            joint2.motorSpeed = 0.0
        else:
            # Stop
            joint1.motorSpeed = 0.0
            joint2.motorSpeed = 0.0
    else:
        # No wall case (though wall is present per task description)
        if step_count < 10:
